 1	using System.Text;
 2	
 3	namespace Slice;
 4	
 5	public sealed class SliceApplication
 6	{
 7	    private readonly Stream _output;
 8	    private readonly TextWriter _error;
 9	
10	    public SliceApplication(Stream output, TextWriter error)
11	    {
12	        _output = output ?? throw new ArgumentNullException(nameof(output));
13	        _error = error ?? throw new ArgumentNullException(nameof(error));
14	    }
15	
16	    public async Task<int> RunAsync(IReadOnlyList<string> args)
17	    {
18	        if (args.Count != 1)
19	        {
20	            await _error.WriteLineAsync("Usage: slice <csv-file>");
21	            return 1;
22	        }
23	
24	        var inputPath = args[0];
25	        if (!File.Exists(inputPath))
26	        {
27	            await _error.WriteLineAsync($"File not found: {inputPath}");
28	            return 1;
29	        }
30	
31	        await using var input = File.OpenRead(inputPath);
32	        await input.CopyToAsync(_output).ConfigureAwait(false);
33	        await _output.FlushAsync().ConfigureAwait(false);
34	        return 0;
35	    }
36	}

