10	    [TestMethod]
11	    public async Task RunAsync_WithCsvFile_WritesTheSameBytesToStandardOutput()
12	    {
13	        var tempFile = Path.Combine(Path.GetTempPath(), $"{Guid.NewGuid():N}.csv");
14	        var expected = "Name,Age\r\nAda,36\r\n\"Lovelace, Ada\",37\r\n";
15	        var expectedBytes = new UTF8Encoding(encoderShouldEmitUTF8Identifier: false).GetBytes(expected);
16	
17	        try
18	        {
19	            await File.WriteAllBytesAsync(tempFile, expectedBytes);
20	
21	            await using var output = new MemoryStream();
22	            var app = new SliceApplication(output, TextWriter.Null);
23	
24	            var exitCode = await app.RunAsync([tempFile]);
25	
26	            Assert.AreEqual(0, exitCode);
27	            CollectionAssert.AreEqual(expectedBytes, output.ToArray());
28	        }
29	        finally
30	        {
31	            if (File.Exists(tempFile))
32	            {
33	                File.Delete(tempFile);
34	            }
35	        }
36	    }
37	
38	    [TestMethod]
39	    public async Task RunAsync_WithMissingFile_ReturnsAnError()
40	    {
41	        await using var output = new MemoryStream();
42	        var error = new StringWriter();
43	        var app = new SliceApplication(output, error);
44	
45	        var exitCode = await app.RunAsync(["missing.csv"]);
46	
47	        Assert.AreEqual(1, exitCode);
48	        StringAssert.Contains(error.ToString(), "File not found");
49	        Assert.AreEqual(0, output.Length);
50	    }
